import{_ as t,o as d,c as o,ag as a}from"./chunks/framework.HG0H2VLS.js";const u=JSON.parse('{"title":"Elevation & Shadows","description":"","frontmatter":{},"headers":[],"relativePath":"tokens/elevation-shadows.md","filePath":"tokens/elevation-shadows.md"}'),s={name:"tokens/elevation-shadows.md"};function r(c,e,n,i,l,h){return d(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="elevation-shadows" tabindex="-1">Elevation &amp; Shadows <a class="header-anchor" href="#elevation-shadows" aria-label="Permalink to &quot;Elevation &amp; Shadows&quot;">​</a></h1><h2 id="elevation" tabindex="-1">Elevation <a class="header-anchor" href="#elevation" aria-label="Permalink to &quot;Elevation&quot;">​</a></h2><p>Elevation communicates depth — surfaces that float above other surfaces. The system uses two levels.</p><h3 id="the-problem-elevation-solves" tabindex="-1">The problem elevation solves <a class="header-anchor" href="#the-problem-elevation-solves" aria-label="Permalink to &quot;The problem elevation solves&quot;">​</a></h3><ul><li><strong>Light mode:</strong> Shadows alone convey depth. Elevated surfaces stay white.</li><li><strong>Dark mode:</strong> Shadows are nearly invisible (dark on dark). Elevated surfaces must get <strong>lighter</strong> to communicate &quot;above.&quot;</li></ul><h3 id="elevation-levels" tabindex="-1">Elevation levels <a class="header-anchor" href="#elevation-levels" aria-label="Permalink to &quot;Elevation levels&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Level</th><th>Token</th><th>Use</th></tr></thead><tbody><tr><td>Base</td><td><code>--ai-surface-primary</code></td><td>Page background</td></tr><tr><td>Level 1</td><td><code>--ai-surface-elevated-1</code></td><td>Cards, dropdowns, popovers, modals</td></tr><tr><td>Level 2</td><td><code>--ai-surface-elevated-2</code></td><td>Content sitting on an elevated-1 surface</td></tr></tbody></table><h3 id="values-across-modes" tabindex="-1">Values across modes <a class="header-anchor" href="#values-across-modes" aria-label="Permalink to &quot;Values across modes&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Token</th><th>Light</th><th>Dark</th><th>Chat Light</th><th>Chat Dark</th></tr></thead><tbody><tr><td><code>--ai-surface-primary</code></td><td><code>#FFFFFF</code></td><td><code>#1B1B1F</code></td><td><code>#FFFFFF</code></td><td><code>#212123</code></td></tr><tr><td><code>--ai-surface-elevated-1</code></td><td><code>#FFFFFF</code></td><td><code>#212123</code></td><td><code>#FFFFFF</code></td><td><code>#2E2E32</code></td></tr><tr><td><code>--ai-surface-elevated-2</code></td><td><code>#FFFFFF</code></td><td><code>#2E2E32</code></td><td><code>#FFFFFF</code></td><td><code>#3C3C3F</code></td></tr></tbody></table><p>Each step is one notch up the Neutral palette in dark mode.</p><h3 id="components-using-elevation" tabindex="-1">Components using elevation <a class="header-anchor" href="#components-using-elevation" aria-label="Permalink to &quot;Components using elevation&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Component</th><th>Level</th><th>Why</th></tr></thead><tbody><tr><td>StyleSettings panel</td><td><code>elevated-1</code></td><td>Floating settings modal</td></tr><tr><td>SystemRole modal</td><td><code>elevated-1</code></td><td>Full-screen / floating modal</td></tr><tr><td>VersionHistoryRow (Selected)</td><td><code>elevated-1</code></td><td>Selected row on elevated panel</td></tr><tr><td>VersionHistoryRow (Live)</td><td><code>elevated-2</code></td><td>Highlighted row on elevated panel</td></tr><tr><td>VersionHistoryRow (Selected &amp; Live)</td><td><code>elevated-2</code></td><td>Combined state</td></tr><tr><td>ChatHeader dropdown</td><td><code>surface-secondary</code></td><td>Dropdown on chat surface</td></tr></tbody></table><h2 id="shadows" tabindex="-1">Shadows <a class="header-anchor" href="#shadows" aria-label="Permalink to &quot;Shadows&quot;">​</a></h2><p>Shadow tokens provide the visual depth cue in light mode and supplementary depth in dark mode.</p><h3 id="shadow-scale" tabindex="-1">Shadow scale <a class="header-anchor" href="#shadow-scale" aria-label="Permalink to &quot;Shadow scale&quot;">​</a></h3><p>Seven steps, from the Figma <code>shadow/*</code> effect styles (redefined 2026-09-23). Every layer is pure black; from <code>sm</code> up the lower layer has a negative spread, so the shadow is cast downward.</p><table tabindex="0"><thead><tr><th>Token</th><th>Light</th><th>Dark (× 2)</th><th>Use</th></tr></thead><tbody><tr><td><code>--ai-shadow-2xs</code></td><td><code>0 1px 0 rgba(0,0,0,0.05)</code></td><td><code>… 0.1</code></td><td>Contact line — Seating Planner cards, listing grid cards</td></tr><tr><td><code>--ai-shadow-xs</code></td><td><code>0 1px 2px rgba(0,0,0,0.05)</code></td><td><code>… 0.1</code></td><td>—</td></tr><tr><td><code>--ai-shadow-sm</code></td><td><code>0 1px 3px 0 rgba(0,0,0,0.1), 0 1px 2px -1px rgba(0,0,0,0.1)</code></td><td><code>… 0.2</code></td><td>Small dropdowns, toggle thumbs</td></tr><tr><td><code>--ai-shadow-md</code></td><td><code>0 4px 6px -1px rgba(0,0,0,0.1), 0 2px 4px -2px rgba(0,0,0,0.1)</code></td><td><code>… 0.2</code></td><td>Tooltips, inputs, menus, toasts</td></tr><tr><td><code>--ai-shadow-lg</code></td><td><code>0 10px 15px -3px rgba(0,0,0,0.1), 0 4px 6px -4px rgba(0,0,0,0.1)</code></td><td><code>… 0.2</code></td><td>—</td></tr><tr><td><code>--ai-shadow-xl</code></td><td><code>0 20px 25px -5px rgba(0,0,0,0.1), 0 8px 10px -6px rgba(0,0,0,0.1)</code></td><td><code>… 0.2</code></td><td>Modals, panels, popovers</td></tr><tr><td><code>--ai-shadow-2xl</code></td><td><code>0 25px 50px -12px rgba(0,0,0,0.1), 0 8px 10px -6px rgba(0,0,0,0.1)</code></td><td><code>… 0.2</code></td><td>—</td></tr></tbody></table><p>Two component-specific shadows sit off the scale: <code>--ai-shadow-card</code> (an even 10px halo, AudioPlayer) and <code>--ai-shadow-cc-rail</code> (the docked CC sidebar&#39;s edge, <code>none</code> in dark).</p><h3 id="dark-mode" tabindex="-1">Dark mode <a class="header-anchor" href="#dark-mode" aria-label="Permalink to &quot;Dark mode&quot;">​</a></h3><p>Dark alphas are <strong>light × 2</strong>, geometry unchanged — a 5–10% black shadow almost vanishes on a dark surface, so the alpha is scaled to keep the same perceived depth. The one exception is <code>--ai-shadow-cc-rail</code>, which is <code>none</code> in dark.</p><h3 id="when-to-use" tabindex="-1">When to use <a class="header-anchor" href="#when-to-use" aria-label="Permalink to &quot;When to use&quot;">​</a></h3><ul><li><strong><code>shadow-2xs</code></strong> — resting cards that only need a contact line</li><li><strong><code>shadow-sm</code></strong> — small floating elements close to the surface</li><li><strong><code>shadow-md</code></strong> — tooltips, inputs, menus, toasts</li><li><strong><code>shadow-xl</code></strong> — modals (SystemRole), panels (AiAssistant, ControlScreen), popovers (DatePicker), floating widgets (AiChatMinimised)</li><li><strong><code>xs</code>, <code>lg</code>, <code>2xl</code></strong> — on the scale, not yet used</li></ul><h3 id="source" tabindex="-1">Source <a class="header-anchor" href="#source" aria-label="Permalink to &quot;Source&quot;">​</a></h3><p><code>css/tokens-shadows.css</code> — static file, manually maintained (shadows cannot be exported as DTCG variables from Figma).</p><h2 id="gradients" tabindex="-1">Gradients <a class="header-anchor" href="#gradients" aria-label="Permalink to &quot;Gradients&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Token</th><th>Direction</th><th>Formula</th><th>Use</th></tr></thead><tbody><tr><td><code>--ai-gradient-surface-secondary</code></td><td><code>to right</code></td><td><code>transparent(secondary) → secondary</code></td><td>Edge fade overlays</td></tr><tr><td><code>--ai-gradient-surface-primary</code></td><td><code>to bottom</code></td><td><code>transparent(primary) → primary</code></td><td>Chat content fade above sticky input</td></tr></tbody></table><p>The chat gradient (<code>--ai-gradient-surface-primary</code>) is <strong>re-declared</strong> under <code>[data-surface=&quot;chat&quot;]</code> and <code>[data-theme=&quot;dark&quot;] [data-surface=&quot;chat&quot;]</code> in <code>tokens-gradients.css</code> because CSS custom properties containing gradient values resolve <code>var()</code> at definition scope, not use scope.</p><h3 id="source-1" tabindex="-1">Source <a class="header-anchor" href="#source-1" aria-label="Permalink to &quot;Source&quot;">​</a></h3><p><code>css/tokens-gradients.css</code> — static file, manually maintained. Uses CSS Relative Color Syntax so dark mode is automatic.</p>',29)])])}const m=t(s,[["render",r]]);export{u as __pageData,m as default};
